    align-items: center;
    justify-content: center;
    inline-size: var(--cascivo-calendar-cell-size);
    block-size: var(--cascivo-calendar-cell-size);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    background: none;
    border: none;
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;
    outline: none;

    &:hover:not([aria-disabled]) {
      background-color: var(--cascivo-color-bg-subtle);
    }
    &:focus-visible {
      box-shadow: var(--cascivo-focus-ring);
    }
    &[data-today] {
      font-weight: var(--cascivo-font-semibold);
      color: var(--cascivo-calendar-day-today-color);
    }
    &[data-in-range] {
      background-color: var(--cascivo-calendar-range-bg);
    }
    &[data-selected],
    &[data-range-start],
    &[data-range-end] {
      background-color: var(--cascivo-calendar-day-selected-bg);
      color: var(--cascivo-calendar-day-selected-fg);
    }
    &[aria-disabled] {
      opacity: 0.35;
      cursor: not-allowed;
    }
  }
  .srOnly {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  .weekNumber {
    font-size: var(--cascivo-text-xs);
    font-weight: var(--cascivo-font-normal);
    color: var(--cascivo-color-text-muted);
    text-align: center;
    padding-inline-end: var(--cascivo-space-1);
  }

  .footer {
    display: flex;
    justify-content: center;
    padding-block-start: var(--cascivo-space-2);
    border-block-start: 1px solid var(--cascivo-color-border);
  }

  .todayButton {
    padding-inline: var(--cascivo-space-3);
    padding-block: var(--cascivo-space-1);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-accent);
    background: none;
    border: none;
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;

    &:hover:not(:disabled) {
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }

  /* Coarse pointers get the 44px effective target the repo mandates; the day cells were 36px
     and the nav buttons 32px, with no block at all. */
  @media (pointer: coarse) {
    .day,
    .navButton,
    .todayButton {
      min-inline-size: var(--cascivo-target-min-coarse, 2.75rem);
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .day,
  .navButton {
    transition-duration: 1ms;
  }
}

@media (forced-colors: active) {
  .day[aria-selected] {
    forced-color-adjust: none;
    background-color: Highlight;
    color: HighlightText;
  }

  .day[aria-current='date'] {
    outline: 2px solid CanvasText;
    outline-offset: -2px;
  }

  .day[aria-disabled] {
    color: GrayText;
  }

  .navButton:disabled {
    color: GrayText;
  }

  .day[data-selected] {
    outline: 2px solid Highlight;
  }
}
